"use client";

import { useState, useMemo } from "react";
import styles from "./roi-calculator.module.css";

const HOURLY_RATE_OPTIONS = [75, 100, 125, 150, 175, 200];

const PLAN_HOURS: Record<string, number> = {
  starter: 40,
  growth: 80,
  pro: 160,
};

const PLAN_PRICES: Record<string, number> = {
  starter: 999,
  growth: 1999,
  pro: 3499,
};

const PLAN_LABELS: Record<string, string> = {
  starter: "Starter",
  growth: "Growth",
  pro: "Pro",
};

export function RoiCalculator() {
  const [hourlyRate, setHourlyRate] = useState(100);
  const [plan, setPlan] = useState<string>("growth");

  const result = useMemo(() => {
    const planPrice = PLAN_PRICES[plan];
    const hours = PLAN_HOURS[plan];
    const agencyCost = hourlyRate * hours;
    const savings = agencyCost - planPrice;
    const savingsPct = Math.round((savings / agencyCost) * 100);
    const effectiveRate = Math.round(planPrice / hours);
    return { agencyCost, savings, savingsPct, effectiveRate, hours };
  }, [hourlyRate, plan]);

  return (
    <section className={styles["section"]}>
      <div className={styles["inner"]}>
        <div className={styles["header"]}>
          <div className={styles["eyebrow"]}>
            <span>ROI Calculator</span>
          </div>
          <h2 className={styles["heading"]}>
            See How Much You Save vs. Hiring
          </h2>
          <p className={styles["subheading"]}>
            Compare what you&apos;d spend on freelancers or contractors vs. a
            Boldteq subscription.
          </p>
        </div>

        <div className={styles["calcCard"]}>
          {/* Controls */}
          <div className={styles["controls"]}>
            {/* Hourly rate selector */}
            <div className={styles["controlGroup"]}>
              <label className={styles["controlLabel"]}>
                Your average hourly rate for developers
              </label>
              <div className={styles["rateOptions"]}>
                {HOURLY_RATE_OPTIONS.map((rate) => (
                  <button
                    key={rate}
                    type="button"
                    className={`${styles["rateBtn"]} ${hourlyRate === rate ? styles["rateBtnActive"] : ""}`}
                    onClick={() => setHourlyRate(rate)}
                  >
                    ${rate}/hr
                  </button>
                ))}
              </div>
            </div>

            {/* Plan selector */}
            <div className={styles["controlGroup"]}>
              <label className={styles["controlLabel"]}>
                Boldteq plan
              </label>
              <div className={styles["planOptions"]}>
                {Object.keys(PLAN_PRICES).map((p) => (
                  <button
                    key={p}
                    type="button"
                    className={`${styles["planBtn"]} ${plan === p ? styles["planBtnActive"] : ""}`}
                    onClick={() => setPlan(p)}
                  >
                    <span className={styles["planBtnName"]}>
                      {PLAN_LABELS[p]}
                    </span>
                    <span className={styles["planBtnPrice"]}>
                      ${PLAN_PRICES[p].toLocaleString()}/mo
                    </span>
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Results */}
          <div className={styles["results"]}>
            <div className={styles["resultRow"]}>
              <span className={styles["resultLabel"]}>
                Equivalent freelancer cost
                <span className={styles["resultNote"]}>
                  ({result.hours} hrs × ${hourlyRate}/hr)
                </span>
              </span>
              <span className={styles["resultValueMuted"]}>
                ${result.agencyCost.toLocaleString()}
              </span>
            </div>

            <div className={styles["resultRow"]}>
              <span className={styles["resultLabel"]}>
                Boldteq {PLAN_LABELS[plan]} plan
              </span>
              <span className={styles["resultValueMuted"]}>
                ${PLAN_PRICES[plan].toLocaleString()}
              </span>
            </div>

            <div className={styles["divider"]} />

            <div className={`${styles["resultRow"]} ${styles["resultRowHighlight"]}`}>
              <span className={styles["resultLabelBold"]}>
                You save per month
              </span>
              <div className={styles["savingsGroup"]}>
                <span className={styles["savingsAmount"]}>
                  ${result.savings.toLocaleString()}
                </span>
                <span className={styles["savingsBadge"]}>
                  {result.savingsPct}% less
                </span>
              </div>
            </div>

            <div className={styles["effectiveRate"]}>
              Effective hourly rate with Boldteq:{" "}
              <strong className={styles["effectiveRateValue"]}>
                ${result.effectiveRate}/hr
              </strong>{" "}
              vs ${hourlyRate}/hr for freelancers
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

